function s(e){let t=e.trim().replace(/^\$/,"").replace(/\s/g,"");if(t===""||(/,\d{1,2}$/.test(t)&&!t.includes(".")&&(t=t.replace(/,(\d{1,2})$/,".$1")),t=t.replace(/,/g,""),!/^\d+(\.\d{0,2})?$/.test(t)))return null;const[r="0",n=""]=t.split("."),a=Number(r)*100+Number((n+"00").slice(0,2));return Number.isSafeInteger(a)?a:null}function o(e){const t=e<0,r=Math.abs(Math.trunc(e));return`${t?"-":""}${Math.floor(r/100)}.${String(r%100).padStart(2,"0")}`}function c(e,t="MXN"){const r=e<0,n=Math.abs(Math.trunc(e)),a=String(Math.floor(n/100)).replace(/\B(?=(\d{3})+(?!\d))/g,",");return`${r?"-":""}$${a}.${String(n%100).padStart(2,"0")} ${t}`}export{o as c,c as f,s as p};
